/**
 * @summary Get purchases
 */
export const getGetAchatsUrl = (params?: GetAchatsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/achats?${stringifiedParams}`
    : `/api/achats`;
};

export const getAchats = async (
  params?: GetAchatsParams,
  options?: RequestInit,
): Promise<AchatsPaginated> => {
  return customFetch<AchatsPaginated>(getGetAchatsUrl(params), {
    ...options,
    method: "GET",
  });
};

